mapper.select:
select c.*
from lab_consumable c
join lab l on l.id = c.lab_id
where c.deleted = 0
  and l.deleted = 0

    and c.lab_id = #{labId}


    and l.lab_type = #{labType}


    and c.consumable_name like concat('%', #{consumableName}, '%')


    and c.consumable_code like concat('%', #{consumableCode}, '%')


    and l.department_id = #{departmentId}


    and c.status = #{status}

order by c.id desc
limit #{offset}, #{pageSize}

select count(*)
from lab_consumable c
join lab l on l.id = c.lab_id
where c.deleted = 0
  and l.deleted = 0

    and c.lab_id = #{labId}


    and l.lab_type = #{labType}


    and c.consumable_name like concat('%', #{consumableName}, '%')


    and c.consumable_code like concat('%', #{consumableCode}, '%')


    and l.department_id = #{departmentId}


    and c.status = #{status}

select c.* from lab_consumable c join lab l on l.id = c.lab_id where c.deleted = 0 and l.deleted = 0 and c.stock_quantity <= c.warning_threshold
and l.department_id = #{departmentId}
order by c.id desc

mapper.update:
update lab_consumable
set stock_quantity = #{stockQuantity}
where id = #{id}
    and deleted = 0

update lab_consumable
set stock_quantity = stock_quantity - #{quantity}
where id = #{id}
    and deleted = 0
    and stock_quantity >= #{quantity}
